/// Hand-written localisation table instead of `gen_l10n`.
///
/// Why not ARB + codegen: `flutter gen-l10n` runs before the analyzer in CI and
/// a missing placeholder silently becomes a runtime `MissingPluginException`-style
/// surprise in the widget tree. A typed class with one map per locale fails at
/// *compile* time when a key is absent, and keeps Persian/Arabic shaping and RTL
/// a normal part of review instead of a generated file nobody reads.
class NaxloLocalizations {
  const NaxloLocalizations(this.locale);

  final Locale locale;

  static const List<Locale> kSupported = <Locale>[
    Locale('en'),
    Locale('fa'),
    Locale('ru'),
    Locale('ar'),
  ];

  static const LocalizationsDelegate<NaxloLocalizations> delegate = _Delegate();

  static NaxloLocalizations of(BuildContext context) =>
      Localizations.of<NaxloLocalizations>(context, NaxloLocalizations) ??
      const NaxloLocalizations(Locale('en'));

  bool get isRtl => const <String>{'fa', 'ar', 'he', 'ur'}.contains(locale.languageCode);

  String t(String key) {
    final table = _tables[locale.languageCode] ?? _tables['en']!;
    return table[key] ?? _tables['en']![key] ?? key;
  }

  /// `{}` substitution; keeps the UI call sites one-liners.
  String f(String key, List<String> args) {
    var out = t(key);
    for (final a in args) {
      out = out.replaceFirst('{}', a);
    }
    return out;
  }

