class _Delegate extends LocalizationsDelegate<NaxloLocalizations> {
  const _Delegate();

  @override
  bool isSupported(Locale locale) => NaxloLocalizations._tables.containsKey(locale.languageCode);

  @override
  Future<NaxloLocalizations> load(Locale locale) async => NaxloLocalizations(locale);

  @override
  bool shouldReload(_Delegate old) => false;
}
